export function detectLang(){
  try{
    const s=localStorage.getItem('tft-lang');
    if(s==='en'||s==='ja'||s==='ar') return s;
  }catch(e){}
  return 'ar';
}
export let lang=detectLang();
export let patchVersion='';
export function setPatchVersion(v){patchVersion=v;applyLanguage()}
export const t=k=>((copy[lang]&&copy[lang][k])||copy.en[k]||k).replace('{v}',patchVersion);
export function localize(value){return value?.[lang]??value?.en??value?.ar??''}
export const LANGS=['ar','en','ja'];
export function nextLang(){return LANGS[(LANGS.indexOf(lang)+1)%LANGS.length]}
export function localePath(page='',target=lang){
  return page;
}
export function currentLocaleUrl(target=lang){
  return location.pathname+location.search;
}
export const LANG_LABEL={ar:'عربي',en:'EN',ja:'日本語'};
export function applyLanguage(){
  document.documentElement.lang=lang;
  document.documentElement.dir=lang==='ar'?'rtl':'ltr';
  document.querySelectorAll('[data-i18n]').forEach(el=>{
    const k=el.getAttribute('data-i18n');
    if(k) el.innerHTML=t(k);
  });
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{
    const k=el.getAttribute('data-i18n-placeholder');
    if(k) el.setAttribute('placeholder', t(k));
  });
  document.querySelectorAll('.lang-toggle').forEach(btn=>{
    btn.textContent=LANG_LABEL[lang]||lang.toUpperCase();
  });
  document.querySelectorAll('.lang-menu [data-lang]').forEach(opt=>{
    opt.classList.toggle('active', opt.getAttribute('data-lang')===lang);
  });
}
function ensureLangMenuCss(){
  if(document.getElementById('lang-menu-css')) return;
  const s=document.createElement('style');
  s.id='lang-menu-css';
  s.textContent=`.lang-wrap{position:relative;display:inline-flex;align-items:center;z-index:90}.lang-menu{position:absolute;top:calc(100% + 8px);inset-inline-end:0;z-index:100;min-width:128px;padding:6px;border-radius:12px;background:rgba(18,24,39,.98);border:1px solid rgba(255,255,255,.12);box-shadow:0 12px 32px rgba(0,0,0,.45);display:none;flex-direction:column;gap:4px}.lang-wrap.open .lang-menu{display:flex}.lang-menu button{appearance:none;border:0;background:transparent;color:#f6f1e8;font:600 13px Outfit,Cairo,sans-serif;text-align:start;padding:8px 12px;border-radius:8px;cursor:pointer;width:100%}.lang-menu button:hover{background:rgba(255,255,255,.06)}.lang-menu button.active{background:rgba(233,185,100,.15);color:#e9b964}`;
  document.head.appendChild(s);
}
function bindLangMenu(onChange){
  ensureLangMenuCss();
  document.querySelectorAll('.lang-toggle').forEach(btn=>{
    if(btn.dataset.langMenuBound) return;
    btn.dataset.langMenuBound='1';
    let wrap=btn.closest('.lang-wrap');
    if(!wrap){
      wrap=document.createElement('div');
      wrap.className='lang-wrap';
      btn.parentNode.insertBefore(wrap, btn);
      wrap.appendChild(btn);
    }
    let menu=wrap.querySelector('.lang-menu');
    if(!menu){
      menu=document.createElement('div');
      menu.className='lang-menu';
      menu.setAttribute('role','menu');
      menu.innerHTML=['ar','en','ja'].map(code=>
        `<button type="button" role="menuitem" data-lang="${code}" class="${code===lang?'active':''}">${LANG_LABEL[code]}</button>`
      ).join('');
      wrap.appendChild(menu);
    }
    btn.setAttribute('aria-haspopup','true');
    btn.setAttribute('aria-expanded','false');
    btn.addEventListener('click',e=>{
      e.stopPropagation();
      const open=wrap.classList.toggle('open');
      btn.setAttribute('aria-expanded', open?'true':'false');
    });
    menu.querySelectorAll('[data-lang]').forEach(opt=>{
      opt.addEventListener('click',e=>{
        e.stopPropagation();
        const next=opt.getAttribute('data-lang');
        if(!next||next===lang){ wrap.classList.remove('open'); btn.setAttribute('aria-expanded','false'); return; }
        lang=next;
        try{ localStorage.setItem('tft-lang',lang); }catch(err){}
        wrap.classList.remove('open');
        btn.setAttribute('aria-expanded','false');
        applyLanguage();
        if(typeof onChange==='function') onChange();
      });
    });
  });
  if(!document.documentElement.dataset.langMenuDoc){
    document.documentElement.dataset.langMenuDoc='1';
    document.addEventListener('click',()=>{
      document.querySelectorAll('.lang-wrap.open').forEach(w=>{
        w.classList.remove('open');
        const b=w.querySelector('.lang-toggle');
        if(b) b.setAttribute('aria-expanded','false');
      });
    });
  }
}
export function setupLanguage(onChange){
  applyLanguage();
  bindLangMenu(onChange);
}
